package com.example.inventory;

import java.sql.*;
import java.util.*;

public class ProductSearchDao {
    private static final Set<String> DIRECTIONS = Set.of("ASC", "DESC");
    private final Connection conn;

    public ProductSearchDao(Connection conn) {
        this.conn = conn;
    }

    public List<String> search(String category, String sortBy, String dir, int limit)
            throws SQLException {
        String direction = DIRECTIONS.contains(dir.toUpperCase()) ? dir.toUpperCase() : "ASC";
        int safeLimit = Math.min(Math.max(limit, 1), 100);
        String sql = "SELECT name FROM products WHERE category = ? AND active = 1"
                + " ORDER BY " + sortBy + " " + direction
                + " LIMIT " + safeLimit;
        List<String> names = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, category);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    names.add(rs.getString("name"));
                }
            }
        }
        return names;
    }
}

